import { getSQLDate } from '@helpers/dateHelper';

import {
  IHikingArticleCreateDTO,
  IHikingArticleDTO,
  IHikingArticleUpdateDTO,
} from '../@types/DTO/hikingArticles.dto.types';
import { IHikingArticle, IHikingArticleWithText } from '../@types/hikingArticles.types';

export const mapHikingArticleToFront = (backData: IHikingArticleDTO): IHikingArticle => {
  return {
    id: +backData.id,
    article: {
      id: +backData.id_article,
      name: backData.article_name,
      created_at: new Date(backData.created_at),
      updated_at: backData.article_updated_at ? new Date(backData.article_updated_at) : null,
      publish_at: backData.article_publish_at ? new Date(backData.article_publish_at) : null,
      author: {
        id: +backData.article_author_id,
        name: backData.article_author_name,
        surname: backData.article_author_surname,
        photo: backData.article_author_photo,
      },
    },
    comment: backData.comment,
    actual_in: backData.actual_in ? new Date(backData.actual_in) : null,
    actual_out: backData.actual_out ? new Date(backData.actual_out) : null,

    author: {
      id: +backData.id_author,
      name: backData.author_name,
      surname: backData.author_surname,
      photo: backData.author_photo,
    },
    created_at: new Date(backData.created_at),
    updated_at: backData.updated_at ? new Date(backData.updated_at) : null,
  };
};

export const mapHikingArticleWithTextToFront = (
  backData: IHikingArticleDTO,
): IHikingArticleWithText => {
  const base = mapHikingArticleToFront(backData);
  return { ...base, article: { ...base.article, text: backData.article_text } };
};

export const mapHikingArticleToAdd = (
  id_hiking: number,
  hikingArticle: IHikingArticle,
): IHikingArticleCreateDTO => {
  return {
    id_hiking,
    id_article: hikingArticle.article.id,
    comment: hikingArticle.comment,

    actual_in: hikingArticle.actual_in ? getSQLDate(hikingArticle.actual_in) : null,
    actual_out: hikingArticle.actual_out ? getSQLDate(hikingArticle.actual_out) : null,
  };
};

export const mapHikingArticleToUpdate = (
  id_hiking: number,
  article: IHikingArticle,
): IHikingArticleUpdateDTO => {
  return {
    ...mapHikingArticleToAdd(id_hiking, article),
    id_hiking,
    id: article.id,
  };
};

export const getEmptyHikingArticle = (
  d: Pick<IHikingArticle, 'author' | 'article'>,
  p: Partial<IHikingArticle> = {},
): IHikingArticle => {
  return {
    id: 0,
    comment: '',
    actual_in: null,
    actual_out: null,

    author: d.author,
    created_at: new Date(),
    updated_at: null,
    article: d.article,
    ...p,
  };
};
